function readBank() {
	const raw = fs.readFileSync(bankPath, 'utf8');
	const marker = 'export const DEV_PRACTICE_QUESTIONS';
	const markerAt = raw.indexOf(marker);
	if (markerAt < 0) throw new Error('Could not find DEV_PRACTICE_QUESTIONS');
