		issues.push(
			`Advanced contentDifficulty ${advanced}/${tagged} (${Math.round((advanced / tagged) * 100)}%) below minimum ${Math.round(CIS_DF_ADVANCED_MIN_RATIO * 100)}%`
		);
	}
	return issues;
